arguments.query:
query {
      games(first: 100, orderBy: "id", orderDir: "asc") {
        nodes { id name slug status releaseDate studio { id name slug } platforms { id name slug } }
        pageInfo { total hasMore nextOffset }
      }
      studio(slug: "fromsoftware") {
        id name slug status
        games(first: 50, orderBy: "id", orderDir: "asc") {
          nodes { id name slug status releaseDate }
          pageInfo { total hasMore nextOffset }
        }
      }
      platforms(first: 50, orderBy: "id", orderDir: "asc") {
        nodes { id name slug status manufacturer }
        pageInfo { total hasMore nextOffset }
      }
    }
